      <div class="post">
        <header class="post-header">
          <h1 class="post-title">
            {% if site.title == "blank" -%}<span class="font-weight-bold">{{ site.first_name }}</span> {{ site.middle_name }} {{ site.last_name }}{%- else -%}{{ site.title }}{%- endif %}
          </h1>
          <p class="desc">{{ page.subtitle }}</p>
        </header>

        <article>
          {% if page.profile -%}
          <div class="profile float-{%- if page.profile.align == 'left' -%}left{%- else -%}right{%- endif -%}">
            {%- if page.profile.image %}
              {%- assign profile_image_path = page.profile.image | prepend: 'assets/img/' -%}

              {% if page.profile.image_circular %}
                {%- assign profile_image_class = "img-fluid z-depth-1 rounded-circle" -%}
              {% else %}
                {%- assign profile_image_class = "img-fluid z-depth-1 rounded" -%}
              {% endif %}

              {% include figure.html
              path=profile_image_path
              class=profile_image_class
              alt=page.profile.image
              cache_bust=true -%}
            {% endif -%}
            {%- if page.profile.address %}
            <div class="address">
              {{ page.profile.address }}
            </div>
            {%- endif %}
          </div>
          {%- endif %}

          <div class="clearfix">
            {{ content }}
          </div>

          <!-- Selected papers -->
          {% if page.selected_papers -%}
          <section class="page-section">
            <h2 class="page-section-title"><a href="{{ '/publications/' | relative_url }}">selected publications</a></h2>
            {%- include selected_papers.html %}
          </section>
          {%- endif %}

          <!-- Affiliations -->
          {% if page.timeline  -%}
          <section class="page-section">
            <h2 class="page-section-title"><a href="{{ '/timeline/' | relative_url }}">affiliations and internships</a></h2>
            {%- include horizontal_timeline.html %}
          </section>
          {%- endif %}

          <!-- News -->
          {% if page.news and site.announcements.enabled -%}
          <section class="page-section">
            <h2 class="page-section-title"><a href="{{ '/news/' | relative_url }}">news</a></h2>
            {%- include news.html limit=true %}
          </section>
          {%- endif %}

          <!-- Latest posts -->
          {% if page.latest_posts -%}
          <section class="page-section">
            <h2 class="page-section-title"><a href="{{ '/blog/' | relative_url }}">latest posts</a></h2>
            {%- include latest_posts.html %}
          </section>
          {%- endif %}

          <!-- Collaborators -->
          {% if page.collaborators -%}
          <section class="page-section">
            <h2 class="page-section-title">mentors and collaborators</h2>
            {%- include collaborators.html %}
          </section>
          {%- endif %}

          <!-- Reviewing -->
          {% if page.reviewing -%}
          <section class="page-section">
            <h2 class="page-section-title">services</h2>
            <h3 class="page-subsection-title">reviewing</h3>
            {%- include reviewing.html %}
          </section>
          {%- endif %}

          <!-- Social -->
          {%- if page.social %}
          <section class="page-section page-section--contact">
            <div class="social">
              <div class="contact-icons">
                {% include social.html %}
              </div>

              <div class="contact-note">
                {{ site.contact_note }}
              </div>

            </div>
          </section>
          {%- endif %}
        </article>

</div>
